// Registers the test-only modules (tests/**/*_register.cpp, list generated by cmake/RigModules.cmake) before main.
#include "api/registry.h"

#define RIG_MODULE(name) void rig_register_##name(rig::Registry &);
#include "rig_test_modules.inc"
#undef RIG_MODULE

namespace {

struct RegisterTestModules {
  RegisterTestModules() {
    rig::Registry &r = rig::Registry::global();
#define RIG_MODULE(name) rig_register_##name(r);
#include "rig_test_modules.inc"
#undef RIG_MODULE
    (void)r;
  }
} g_registerTestModules;

}  // namespace
